// Loads the hand engine out of index.html so the simulator and the tests run
// exactly the code the app ships, with no second copy to keep in sync.
//
// index.html marks two blocks with line comments:
//   // ===== ENGINE:BEGIN ... // ===== ENGINE:END        classification, tiebreaks, dealing
//   // ===== RANKINGS:BEGIN ... // ===== RANKINGS:END    generated by simulate.mjs --write
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const INDEX_HTML = fileURLToPath(new URL('../index.html', import.meta.url));

// Top-level names from the blocks that callers may use. Names a block does not
// define come back as undefined.
const EXPORTS = [
  'R', 'S', 'HAND', 'TOTAL', 'JK', 'RN', 'NOSUIT', 'EVEN', 'WINS', 'SPEC', 'TYPES', 'TI', 'DESCS', 'CARDS',
  'dealRandom', 'handStats', 'qualifyFlags', 'qualifies', 'classify', 'rankPos',
  'tiebreakKey', 'compareHands', 'cmpKeys', 'keyLabel', 'valueName',
  'RANKING', 'RANKING_META',
];

function blockRegex(name) {
  return new RegExp(`^([ \\t]*// ===== ${name}:BEGIN[^\\n]*\\n)([\\s\\S]*?)(^[ \\t]*// ===== ${name}:END[^\\n]*)`, 'm');
}

export function extractBlock(html, name) {
  const m = html.match(blockRegex(name));
  if (!m) throw new Error(`${name} block not found in index.html`);
  return m[2];
}

export function replaceBlock(html, name, body) {
  if (!blockRegex(name).test(html)) throw new Error(`${name} block not found in index.html`);
  return html.replace(blockRegex(name), (_, begin, _old, end) => begin + body + end);
}

// rankings: false loads only the engine (the simulator must not depend on the
// ranking it is computing).
export function loadEngine({ rankings = true, html = readFileSync(INDEX_HTML, 'utf8') } = {}) {
  let code = extractBlock(html, 'ENGINE');
  if (rankings) code += '\n' + extractBlock(html, 'RANKINGS');
  const ret = EXPORTS.map((n) => `${n}: typeof ${n} === 'undefined' ? undefined : ${n}`).join(',\n');
  return new Function(`"use strict";\n${code}\nreturn {\n${ret}\n};`)();
}
